begin;
create extension if not exists pgcrypto;

create table if not exists public.angelcare_marketplace_live_experience_capabilities(id uuid primary key default gen_random_uuid(),capability_key text unique not null,kind text not null,description text,status text not null default 'active',created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_live_experience_purposes(id uuid primary key default gen_random_uuid(),purpose_key text unique not null,kind text not null check(kind in('popup','broadcast','proof')),name jsonb not null,domain text not null,default_placement text not null,default_trigger text not null,parameters jsonb not null default '{}',status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_live_experience_themes(id uuid primary key default gen_random_uuid(),theme_key text unique not null,kind text not null check(kind in('popup','broadcast','proof')),name jsonb not null,tokens jsonb not null,composition jsonb not null default '{}',status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_live_experience_presets(id uuid primary key default gen_random_uuid(),preset_key text unique not null,kind text not null,purpose_key text not null references public.angelcare_marketplace_live_experience_purposes(purpose_key),theme_key text not null references public.angelcare_marketplace_live_experience_themes(theme_key),name jsonb not null,configuration jsonb not null default '{}',status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_live_experience_campaigns(id uuid primary key default gen_random_uuid(),campaign_key text unique not null,name text not null,kind text not null check(kind in('popup','broadcast','proof')),purpose_key text not null references public.angelcare_marketplace_live_experience_purposes(purpose_key),theme_key text not null references public.angelcare_marketplace_live_experience_themes(theme_key),status text not null default 'draft' check(status in('draft','scheduled','active','suspended','expired','archived')),priority integer not null default 100,localized_content jsonb not null default '{}',media jsonb not null default '{}',placement jsonb not null default '{}',trigger jsonb not null default '{}',targeting jsonb not null default '{}',frequency jsonb not null default '{}',schedule jsonb not null default '{}',truth_source jsonb not null default '{}',conversion jsonb not null default '{}',experiment_id uuid,starts_at timestamptz,ends_at timestamptz,version integer not null default 1,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_live_experience_versions(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.angelcare_marketplace_live_experience_campaigns(id) on delete restrict,version integer not null,snapshot jsonb not null,created_by uuid,created_at timestamptz not null default now(),unique(campaign_id,version));
create table if not exists public.angelcare_marketplace_live_experience_audiences(id uuid primary key default gen_random_uuid(),audience_key text unique not null,name text not null,audience_type text not null default 'dynamic',definition jsonb not null default '{}',status text not null default 'active',created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_live_experience_placements(id uuid primary key default gen_random_uuid(),placement_key text unique not null,label text not null,family text not null,configuration jsonb not null default '{}',status text not null default 'active',created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_live_experience_schedules(id uuid primary key default gen_random_uuid(),schedule_key text unique not null,campaign_id uuid references public.angelcare_marketplace_live_experience_campaigns(id) on delete cascade,starts_at timestamptz,ends_at timestamptz,timezone text not null default 'Africa/Casablanca',recurrence jsonb not null default '{}',status text not null default 'scheduled',execution_evidence jsonb not null default '{}',created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_live_experience_experiments(id uuid primary key default gen_random_uuid(),experiment_key text unique not null,name text not null,status text not null default 'draft',objective text not null default 'conversion',allocation jsonb not null default '{}',variants jsonb not null default '[]',control_variant text,starts_at timestamptz,ends_at timestamptz,winner_variant text,evidence jsonb not null default '{}',created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.angelcare_marketplace_live_experience_campaigns drop constraint if exists angelcare_marketplace_live_experience_campaigns_experiment_id_fkey;
alter table public.angelcare_marketplace_live_experience_campaigns add constraint angelcare_marketplace_live_experience_campaigns_experiment_id_fkey foreign key(experiment_id) references public.angelcare_marketplace_live_experience_experiments(id) on delete set null;
create table if not exists public.angelcare_marketplace_live_experience_source_snapshots(id uuid primary key default gen_random_uuid(),source_key text unique not null,authority text not null,entity_type text not null,entity_id text,payload jsonb not null default '{}',verified boolean not null default false,observed_at timestamptz not null default now(),expires_at timestamptz,status text not null default 'active',refreshed_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_live_experience_impressions(id uuid primary key default gen_random_uuid(),campaign_id uuid references public.angelcare_marketplace_live_experience_campaigns(id) on delete set null,event_type text not null default 'impression',session_key text,customer_account_id uuid,pathname text not null,locale text not null,device_class text,metadata jsonb not null default '{}',ip_hash text,user_agent text,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_live_experience_interactions(id uuid primary key default gen_random_uuid(),campaign_id uuid references public.angelcare_marketplace_live_experience_campaigns(id) on delete set null,event_type text not null,session_key text,customer_account_id uuid,pathname text not null,locale text not null,device_class text,metadata jsonb not null default '{}',ip_hash text,user_agent text,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_live_experience_conversions(id uuid primary key default gen_random_uuid(),campaign_id uuid references public.angelcare_marketplace_live_experience_campaigns(id) on delete set null,event_type text not null default 'conversion',session_key text,customer_account_id uuid,pathname text not null,locale text not null,device_class text,canonical_object_type text,canonical_object_id text,attribution jsonb not null default '{}',metadata jsonb not null default '{}',ip_hash text,user_agent text,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_live_experience_audit_events(id uuid primary key default gen_random_uuid(),actor_id uuid,action text not null,object_type text not null,object_id text,evidence jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists ac_live_campaign_status_idx on public.angelcare_marketplace_live_experience_campaigns(status,starts_at,ends_at,priority desc);
create index if not exists ac_live_campaign_kind_idx on public.angelcare_marketplace_live_experience_campaigns(kind,purpose_key,theme_key);
create index if not exists ac_live_source_fresh_idx on public.angelcare_marketplace_live_experience_source_snapshots(source_key,verified,status,expires_at);
create index if not exists ac_live_impression_campaign_idx on public.angelcare_marketplace_live_experience_impressions(campaign_id,created_at desc);
create index if not exists ac_live_interaction_campaign_idx on public.angelcare_marketplace_live_experience_interactions(campaign_id,event_type,created_at desc);

select p.purpose_key||'__'||t.theme_key,p.kind,p.purpose_key,t.theme_key,
 jsonb_build_object(
  'fr', (p.name->>'fr') || ' · ' || (t.name->>'fr'),
  'en', (p.name->>'en') || ' · ' || (t.name->>'en'),
  'ar', (p.name->>'ar') || ' · ' || (t.name->>'ar')
 ),
 jsonb_build_object('placement',p.default_placement,'trigger',p.default_trigger,'parameters',p.parameters,'tokens',t.tokens),'active'
from public.angelcare_marketplace_live_experience_purposes p join public.angelcare_marketplace_live_experience_themes t on t.kind=p.kind
on conflict(preset_key) do update set name=excluded.name,configuration=excluded.configuration,status='active';

do $$ begin
 if to_regclass('public.angelcare_marketplace_permissions') is not null then
  on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
 end if;
 if to_regclass('public.angelcare_marketplace_role_permissions') is not null and to_regclass('public.angelcare_marketplace_roles') is not null then
  select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p
  where r.role_key in('marketplace_super_admin','marketplace_executive','marketplace_admin') and (p.permission_key like 'marketplace.%live_experience%' or p.permission_key in('marketplace.popup.manage','marketplace.broadcast.manage','marketplace.proof_widget.manage','marketplace.audience.manage','marketplace.experiment.manage','marketplace.emergency_broadcast.manage'))
  on conflict do nothing;
 end if;
 if to_regclass('public.angelcare_marketplace_modules') is not null then
  values('live-experience-command','Live Experience Command','Popups, broadcasting, flash sale, proof widgets, audiences, experiments and analytics.','/angelcare-marketplace/admin/live-experience-command','enabled',true,'healthy',array['marketplace.live_experience.view']::text[],30,1)
  on conflict(module_key) do update set name=excluded.name,description=excluded.description,route_prefix=excluded.route_prefix,status='enabled',enabled=true,health_status='healthy',required_permissions=excluded.required_permissions,introduced_by_mega_zip=excluded.introduced_by_mega_zip,version=public.angelcare_marketplace_modules.version+1,updated_at=now();
 end if;
 if to_regclass('public.angelcare_marketplace_feature_flags') is not null then
  values('marketplace.live_experience.enabled','Marketplace Live Experience Command','Governed popup, broadcast and proof experience runtime.',true,'active','Live Experience Command installed')
  on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();
 end if;
end $$;
alter table public.angelcare_marketplace_live_experience_capabilities enable row level security; revoke all on table public.angelcare_marketplace_live_experience_capabilities from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_capabilities to service_role;
alter table public.angelcare_marketplace_live_experience_purposes enable row level security; revoke all on table public.angelcare_marketplace_live_experience_purposes from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_purposes to service_role;
alter table public.angelcare_marketplace_live_experience_themes enable row level security; revoke all on table public.angelcare_marketplace_live_experience_themes from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_themes to service_role;
alter table public.angelcare_marketplace_live_experience_presets enable row level security; revoke all on table public.angelcare_marketplace_live_experience_presets from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_presets to service_role;
alter table public.angelcare_marketplace_live_experience_campaigns enable row level security; revoke all on table public.angelcare_marketplace_live_experience_campaigns from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_campaigns to service_role;
alter table public.angelcare_marketplace_live_experience_versions enable row level security; revoke all on table public.angelcare_marketplace_live_experience_versions from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_versions to service_role;
alter table public.angelcare_marketplace_live_experience_audiences enable row level security; revoke all on table public.angelcare_marketplace_live_experience_audiences from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_audiences to service_role;
alter table public.angelcare_marketplace_live_experience_placements enable row level security; revoke all on table public.angelcare_marketplace_live_experience_placements from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_placements to service_role;
alter table public.angelcare_marketplace_live_experience_schedules enable row level security; revoke all on table public.angelcare_marketplace_live_experience_schedules from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_schedules to service_role;
alter table public.angelcare_marketplace_live_experience_experiments enable row level security; revoke all on table public.angelcare_marketplace_live_experience_experiments from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_experiments to service_role;
alter table public.angelcare_marketplace_live_experience_source_snapshots enable row level security; revoke all on table public.angelcare_marketplace_live_experience_source_snapshots from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_source_snapshots to service_role;
alter table public.angelcare_marketplace_live_experience_impressions enable row level security; revoke all on table public.angelcare_marketplace_live_experience_impressions from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_impressions to service_role;
alter table public.angelcare_marketplace_live_experience_interactions enable row level security; revoke all on table public.angelcare_marketplace_live_experience_interactions from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_interactions to service_role;
alter table public.angelcare_marketplace_live_experience_conversions enable row level security; revoke all on table public.angelcare_marketplace_live_experience_conversions from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_conversions to service_role;
alter table public.angelcare_marketplace_live_experience_audit_events enable row level security; revoke all on table public.angelcare_marketplace_live_experience_audit_events from anon,authenticated; grant all on table public.angelcare_marketplace_live_experience_audit_events to service_role;
commit;
select 'live_experience_command_applied' as result,(select count(*) from public.angelcare_marketplace_live_experience_capabilities) as governed_capabilities,(select count(*) from public.angelcare_marketplace_live_experience_purposes where kind='popup') as popup_purposes,(select count(*) from public.angelcare_marketplace_live_experience_purposes where kind='broadcast') as broadcast_purposes,(select count(*) from public.angelcare_marketplace_live_experience_purposes where kind='proof') as proof_purposes,(select count(*) from public.angelcare_marketplace_live_experience_presets) as premium_presets,(select count(*) from public.angelcare_marketplace_live_experience_campaigns where status='active') as active_campaigns;
